-- Generated by scripts/expat-content/build-seed.mjs. Do not edit by hand.
-- Every statement is an upsert on a natural key, so re-running is safe.

-- Sources. Keyed on url, which is unique per source in this set.
insert into public.expat_citations
  (publisher, url, official, published_on, effective_from, observed_at, language, excerpt)
values ('Georgian National Tourism Administration (georgia.travel)', 'https://georgia.travel/cities-towns/mtskheta', true, null, null,
        '2026-10-24T00:00:00Z'::timestamptz, 'en', 'Former capital, about 20 minutes by road from Tbilisi, "sometimes called Little Jerusalem". Svetitskhoveli Cathedral (1010 to 1129) and Jvari Church (6th to 7th century). "Three of Mtskheta''s churches are part of the UNESCO World Heritage List": Jvari, Svetitskhoveli and Samtavro.')
on conflict do nothing;
insert into public.expat_citations
  (publisher, url, official, published_on, effective_from, observed_at, language, excerpt)
values ('Georgian National Tourism Administration (georgia.travel)', 'https://georgia.travel/regions/kakheti', true, null, null,
        '2026-10-24T00:00:00Z'::timestamptz, 'en', 'Kakheti is "Georgia''s premiere winegrowing region", with qvevri winemaking and grapes such as Saperavi and Rkatsiteli, and "the palace of King Erekle (Heraclius) II in Telavi".')
on conflict do nothing;
insert into public.expat_citations
  (publisher, url, official, published_on, effective_from, observed_at, language, excerpt)
values ('Georgian National Tourism Administration (georgia.travel)', 'https://georgia.travel/cities-towns/sighnaghi', true, null, null,
        '2026-10-24T00:00:00Z'::timestamptz, 'en', 'Sighnaghi was "dubbed a City of Love" after restoration from 2007; a nearly intact fortress wall built in 1762; "breathtaking views of Alazani valley and the Greater Caucasus Mountains".')
on conflict do nothing;
insert into public.expat_citations
  (publisher, url, official, published_on, effective_from, observed_at, language, excerpt)
values ('Georgian National Tourism Administration (georgia.travel)', 'https://georgia.travel/regions/mtskheta-mtianeti', true, null, null,
        '2026-10-24T00:00:00Z'::timestamptz, 'en', '"After Tbilisi and Batumi, Kazbegi is one of Georgia''s most popular tourist destinations." Attractions include "the mountain village of Stepantsminda" and "the picture-perfect 14th-century Gergeti Trinity Church" below Kazbegi Mountain (5054m). Gudauri is "the country''s premier ski resort".')
on conflict do nothing;
insert into public.expat_citations
  (publisher, url, official, published_on, effective_from, observed_at, language, excerpt)
values ('Georgian National Tourism Administration (georgia.travel)', 'https://georgia.travel/regions/samegrelo-zemo-svaneti', true, null, null,
        '2026-10-24T00:00:00Z'::timestamptz, 'en', 'Zemo Svaneti is "a high-mountain region and hotspot of tourism and alpinism"; Mestia is its centre. Svan towers "standing 20 to 25 meters high". Zugdidi is "the main city of Samegrelo", with the Dadiani palace, now a state museum.')
on conflict do nothing;
insert into public.expat_citations
  (publisher, url, official, published_on, effective_from, observed_at, language, excerpt)
values ('Georgian National Tourism Administration (georgia.travel)', 'https://georgia.travel/regions/imereti', true, null, null,
        '2026-10-24T00:00:00Z'::timestamptz, 'en', '"Kutaisi was the capital until the Middle Ages." Gelati is a UNESCO World Heritage monument. Bagrati Cathedral, built in 1003, is "a symbol of the country''s unity". Prometheus Cave and Sataplia are listed among the "natural wonders worth seeing in Imereti".')
on conflict do nothing;
insert into public.expat_citations
  (publisher, url, official, published_on, effective_from, observed_at, language, excerpt)
values ('Georgian National Tourism Administration (georgia.travel)', 'https://georgia.travel/regions/samtskhe-javakheti', true, null, null,
        '2026-10-24T00:00:00Z'::timestamptz, 'en', '"One of Georgia''s most well-known mineral waters has its roots in Borjomi"; visitors can drink from a spring in the central park. Borjomi-Kharagauli National Park has hiking routes of one to three days. Vardzia is "a city and monastery carved into a cliffside".')
on conflict do nothing;
insert into public.expat_citations
  (publisher, url, official, published_on, effective_from, observed_at, language, excerpt)
values ('Madloba.info', 'https://madloba.info/en/faq/healthcare-and-insurance/can-you-drink-tap-water-in-georgia/', false, null, null,
        '2026-10-24T00:00:00Z'::timestamptz, 'en', 'In Tbilisi and Batumi "the water utilities say tap water meets drinking standards"; older buildings may have worn pipes, so a filter or bottled water is safer there. In villages and mountains spring water "quality is not always tested". Checked Oct. 3, 2026.')
on conflict do nothing;
