  (publisher, url, official, published_on, effective_from, observed_at, language, excerpt)
values ('Georgian National Tourism Administration (georgia.travel)', 'https://georgia.travel/coming-to-georgia/tipping-culture-in-georgia', false, null, null,
        '2026-10-24T00:00:00Z'::timestamptz, 'en', '"In general, between 10% and 15% of the amount you paid for the service is an optimal tip." "But it depends on you, how much are you willing to pay, and how much you can tip." Tips can be added on Bank of Georgia or TBC Bank cards at the card terminal.')
