-- Keep one row per (publisher, url): re-running must not accumulate copies.
delete from public.expat_citations a
using public.expat_citations b
where a.publisher = b.publisher
  and a.url is not distinct from b.url
  and a.ctid > b.ctid
  and not exists (select 1 from public.expat_fact_citations fc where fc.citation_id = a.id)
  and not exists (select 1 from public.expat_cost_observations co where co.citation_id = a.id)
  and not exists (select 1 from public.expat_places p where p.citation_id = a.id);

-- places-to-visit
insert into public.expat_topics
  (slug, country, domain, pathway, content, fact_class, register, sort_order,
   published, needs_review, review_reason, last_verified_at, review_due_at)
values ('places-to-visit', 'GE', 'DAILY_LIFE', 'LIVE', '{"en":{"title":"Places to visit","summary":"Georgia is small, and that is the good news: high mountains, old churches, wine country and the sea are all within a day of Tbilisi.","sections":[{"kind":"SHORT_ANSWER","heading":"The short answer","body":"Start close to home with Mtskheta, then spend a weekend in Kakheti for wine and Sighnaghi. Go north to Kazbegi for the mountains, west to Kutaisi for monasteries and caves, and save a few days for Svaneti. In summer, Batumi and the sea. The national tourism site, georgia.travel, has more on every place here."},{"kind":"WHERE","heading":"Easy trips from Tbilisi","body":"Mtskheta, the old capital, is about 20 minutes away by road. Svetitskhoveli Cathedral and Jvari Church are there, and three of its churches are on the UNESCO World Heritage List. Kakheti, to the east, is Georgia''s main wine region, where wine is still made in clay qvevri. Sighnaghi, known as the City of Love, has an old town wall and wide views over the Alazani Valley to the Caucasus. Telavi has the palace of King Erekle II."},{"kind":"WHERE","heading":"The mountains","body":"Kazbegi is one of the most visited places in Georgia after Tbilisi and Batumi. From the village of Stepantsminda you can walk or drive up to the 14th century Gergeti Trinity Church below Mount Kazbek, 5054 metres high. On the way is Gudauri, the country''s best known ski resort. Further west, Svaneti is high mountain country with Mestia at its centre and its famous stone towers, 20 to 25 metres tall. The usual road there goes through Zugdidi."},{"kind":"WHERE","heading":"The west and the sea","body":"Kutaisi was the capital until the Middle Ages. See Bagrati Cathedral, built in 1003, and Gelati Monastery, which is on the UNESCO list, then the Prometheus Cave and Sataplia nearby. Batumi is the place for the seaside, with a long Boulevard by the water, and early autumn is a lovely time to go."},{"kind":"WHERE","heading":"Borjomi and Vardzia","body":"Borjomi is a small mountain town famous for its mineral water, which you can drink from a spring in the central park. The Borjomi Kharagauli National Park around it has hikes of one to three days. Further south, Vardzia is a medieval town and monastery cut into a cliff."},{"kind":"PRACTICAL","heading":"Before you go","body":"Mountain roads and weather change with the season, so check the forecast and the road before a winter trip north or to Svaneti. Take your passport on trains. In villages, carry some cash, and a Magti SIM tends to have the best signal in the mountains."}]},"ka":{"title":"სანახავი ადგილები","summary":"საქართველო პატარაა და ეს კარგი ამბავია: მაღალი მთები, ძველი ეკლესიები, ღვინის მხარე და ზღვა თბილისიდან ერთი დღის სავალზეა.","sections":[{"kind":"SHORT_ANSWER","heading":"მოკლე პასუხი","body":"დაიწყეთ ახლოდან, მცხეთით, შემდეგ შაბათ-კვირა გაატარეთ კახეთში ღვინისა და სიღნაღისთვის. მთებისთვის წადით ჩრდილოეთით, ყაზბეგში, მონასტრებისა და მღვიმეებისთვის დასავლეთით, ქუთაისში, და რამდენიმე დღე სვანეთს დაუთმეთ. ზაფხულში კი ბათუმი და ზღვა. ეროვნული ტურისტული საიტი georgia.travel ყოველ ამ ადგილზე მეტს მოგიყვებათ."},{"kind":"WHERE","heading":"მარტივი გასვლები თბილისიდან","body":"მცხეთა, ძველი დედაქალაქი, მანქანით დაახლოებით 20 წუთის სავალზეა. აქ არის სვეტიცხოველი და ჯვრის მონასტერი, მისი სამი ეკლესია კი იუნესკოს მსოფლიო მემკვიდრეობის სიაშია. კახეთი, აღმოსავლეთით, საქართველოს მთავარი ღვინის მხარეა, სადაც ღვინოს დღესაც ქვევრში აყენებენ. სიღნაღს, რომელსაც სიყვარულის ქალაქს ეძახიან, ძველი გალავანი და ალაზნის ველისა და კავკასიონის ფართო ხედი აქვს. თელავში ერეკლე მეორის სასახლეა."},{"kind":"WHERE","heading":"მთები","body":"ყაზბეგი თბილისისა და ბათუმის შემდეგ ერთ-ერთი ყველაზე მონახულებადი ადგილია. სოფელ სტეფანწმინდიდან ფეხით ან მანქანით შეგიძლიათ ახვიდეთ XIV საუკუნის გერგეტის სამებამდე, 5054 მეტრის სიმაღლის მყინვარწვერის ძირას. გზაზე გუდაურია, ქვეყნის ყველაზე ცნობილი სათხილამურო კურორტი. დასავლეთით სვანეთია, მაღალმთიანი მხარე, რომლის ცენტრია მესტია, თავისი ცნობილი ქვის კოშკებით, რომელთა სიმაღლე 20-დან 25 მეტრამდეა. იქ ჩვეულებრივ ზუგდიდის გავლით მიდიან."},{"kind":"WHERE","heading":"დასავლეთი და ზღვა","body":"ქუთაისი შუა საუკუნეებამდე დედაქალაქი იყო. ნახეთ 1003 წელს აგებული ბაგრატის ტაძარი და იუნესკოს სიაში შეტანილი გელათის მონასტერი, შემდეგ კი ახლომდებარე პრომეთეს მღვიმე და სათაფლია. ზღვისთვის ბათუმია, წყლის პირას გრძელი ბულვარით, და ადრეული შემოდგომა მისთვის საუკეთესო დროა."},{"kind":"WHERE","heading":"ბორჯომი და ვარძია","body":"ბორჯომი პატარა მთის ქალაქია, ცნობილი თავისი მინერალური წყლით, რომლის დალევაც ცენტრალური პარკის წყაროდან შეგიძლიათ. ირგვლივ ბორჯომ ხარაგაულის ეროვნული პარკია ერთიდან სამ დღემდე ლაშქრობებით. სამხრეთით ვარძიაა, კლდეში ნაკვეთი შუა საუკუნეების ქალაქი და მონასტერი."},{"kind":"PRACTICAL","heading":"წასვლამდე","body":"მთის გზები და ამინდი სეზონთან ერთად იცვლება, ამიტომ ზამთარში ჩრდილოეთით ან სვანეთში გამგზავრებამდე ნახეთ პროგნოზი და გზის მდგომარეობა. მატარებელში პასპორტი თან იქონიეთ. სოფლებში ცოტა ნაღდი ფული გქონდეთ, მთაში კი, როგორც წესი, მაგთის სიმ ბარათს აქვს საუკეთესო კავშირი."}]},"ru":{"title":"Куда поехать","summary":"Грузия маленькая, и это хорошая новость: высокие горы, древние храмы, винный край и море в пределах дня пути от Тбилиси.","sections":[{"kind":"SHORT_ANSWER","heading":"Коротко","body":"Начните с близкого: Мцхета. Потом проведите выходные в Кахетии ради вина и Сигнахи. За горами езжайте на север, в Казбеги, за монастырями и пещерами на запад, в Кутаиси, и оставьте несколько дней на Сванетию. Летом Батуми и море. На национальном туристическом сайте georgia.travel есть больше о каждом из этих мест."},{"kind":"WHERE","heading":"Близкие поездки из Тбилиси","body":"Мцхета, древняя столица, примерно в 20 минутах езды. Здесь Светицховели и монастырь Джвари, а три её храма входят в список Всемирного наследия ЮНЕСКО. Кахетия на востоке это главный винный регион Грузии, где вино до сих пор делают в глиняных квеври. В Сигнахи, который называют городом любви, сохранилась крепостная стена и широкий вид на Алазанскую долину и Кавказ. В Телави есть дворец царя Ираклия II."},{"kind":"WHERE","heading":"Горы","body":"Казбеги одно из самых посещаемых мест Грузии после Тбилиси и Батуми. Из посёлка Степанцминда можно подняться пешком или на машине к церкви Гергети Самеба XIV века у подножия Казбека высотой 5054 метра. По дороге Гудаури, самый известный горнолыжный курорт страны. Западнее Сванетия, высокогорный край с центром в Местиа и знаменитыми каменными башнями высотой от 20 до 25 метров. Обычно туда едут через Зугдиди."},{"kind":"WHERE","heading":"Запад и море","body":"Кутаиси был столицей до Средних веков. Посмотрите храм Баграта, построенный в 1003 году, и монастырь Гелати из списка ЮНЕСКО, а рядом пещеру Прометея и Сатаплиа. Для моря есть Батуми с длинным Бульваром вдоль воды, и ранняя осень там особенно хороша."},{"kind":"WHERE","heading":"Боржоми и Вардзия","body":"Боржоми небольшой горный город, известный минеральной водой, которую можно пить прямо из источника в центральном парке. Вокруг Боржоми Харагаульский национальный парк с походами от одного до трёх дней. Южнее Вардзия, средневековый город и монастырь, вырезанные в скале."},{"kind":"PRACTICAL","heading":"Перед поездкой","body":"Горные дороги и погода меняются по сезону, поэтому перед зимней поездкой на север или в Сванетию проверьте прогноз и состояние дороги. В поезде нужен паспорт. В сёлах держите немного наличных, а в горах лучшая связь обычно у Magti."}]},"tr":{"title":"Gezilecek yerler","summary":"Gürcistan küçük ve bu iyi haber: yüksek dağlar, eski kiliseler, şarap bölgesi ve deniz Tiflis''ten bir günlük mesafede.","sections":[{"kind":"SHORT_ANSWER","heading":"Kısaca","body":"Yakından, Mtsheta''dan başlayın, sonra şarap ve Sighnaghi için bir hafta sonunu Kaheti''de geçirin. Dağlar için kuzeye, Kazbegi''ye, manastırlar ve mağaralar için batıya, Kutaisi''ye gidin, Svaneti''ye de birkaç gün ayırın. Yazın Batum ve deniz. Ulusal turizm sitesi georgia.travel her yer hakkında daha fazlasını anlatıyor."},{"kind":"WHERE","heading":"Tiflis''ten kolay geziler","body":"Eski başkent Mtsheta arabayla yaklaşık 20 dakika uzaklıkta. Svetitskhoveli Katedrali ve Cvari Kilisesi burada, üç kilisesi UNESCO Dünya Mirası Listesi''nde. Doğudaki Kaheti, şarabın hâlâ toprak küplerde, kvevride yapıldığı Gürcistan''ın ana şarap bölgesi. Aşk Şehri diye bilinen Sighnaghi''nin eski sur duvarı ve Alazani Vadisi''ne, Kafkaslara bakan geniş manzarası var. Telavi''de Kral II. Erekle''nin sarayı bulunur."},{"kind":"WHERE","heading":"Dağlar","body":"Kazbegi, Tiflis ve Batum''dan sonra Gürcistan''ın en çok ziyaret edilen yerlerinden biri. Stepantsminda köyünden yürüyerek ya da arabayla 14. yüzyıldan kalma Gergeti Sameba Kilisesi''ne çıkabilirsiniz, arkasında 5054 metrelik Kazbek Dağı yükselir. Yolda ülkenin en bilinen kayak merkezi Gudauri var. Daha batıda, merkezi Mestia olan ve 20 ila 25 metre yüksekliğindeki ünlü taş kuleleriyle bilinen yüksek dağ bölgesi Svaneti bulunur. Oraya genelde Zugdidi üzerinden gidilir."},{"kind":"WHERE","heading":"Batı ve deniz","body":"Kutaisi Orta Çağ''a kadar başkentti. 1003''te yapılan Bagrati Katedrali''ni ve UNESCO listesindeki Gelati Manastırı''nı görün, ardından yakındaki Prometheus Mağarası ve Sataplia''ya gidin. Deniz için Batum var, su kenarında uzun bir Bulvar ile, erken sonbahar özellikle güzel."},{"kind":"WHERE","heading":"Borjomi ve Vardzia","body":"Borjomi, maden suyuyla ünlü küçük bir dağ kasabası, suyu merkez parktaki kaynaktan içebilirsiniz. Çevresindeki Borjomi Kharagauli Milli Parkı''nda bir ila üç günlük yürüyüş rotaları var. Daha güneyde Vardzia, kayalara oyulmuş Orta Çağ''dan kalma bir şehir ve manastır."},{"kind":"PRACTICAL","heading":"Gitmeden önce","body":"Dağ yolları ve hava mevsime göre değişir, kışın kuzeye ya da Svaneti''ye gitmeden önce hava tahminine ve yol durumuna bakın. Trende pasaportunuz yanınızda olsun. Köylerde biraz nakit taşıyın, dağlarda genelde en iyi çekim Magti''dedir."}]},"ar":{"title":"أماكن تستحق الزيارة","summary":"جورجيا بلد صغير، وهذا خبر جيد: الجبال العالية والكنائس القديمة وأرض النبيذ والبحر كلها على بعد يوم من تبليسي.","sections":[{"kind":"SHORT_ANSWER","heading":"باختصار","body":"ابدأ بالقريب، متسخيتا، ثم اقضِ عطلة نهاية أسبوع في كاخيتي من أجل النبيذ وسيغناغي. اتجه شمالًا إلى كازبيغي للجبال، وغربًا إلى كوتايسي للأديرة والكهوف، واترك بضعة أيام لسفانيتي. وفي الصيف باتومي والبحر. وفي موقع السياحة الوطني georgia.travel معلومات أكثر عن كل هذه الأماكن."},{"kind":"WHERE","heading":"رحلات سهلة من تبليسي","body":"متسخيتا، العاصمة القديمة، على بعد نحو 20 دقيقة بالسيارة. فيها كاتدرائية سفيتيتسخوفيلي وكنيسة جفاري، وثلاث من كنائسها مدرجة في قائمة اليونسكو للتراث العالمي. وكاخيتي في الشرق هي منطقة النبيذ الأولى في جورجيا، وما زال النبيذ يُصنع فيها في جرار الفخار المسماة قفيفري. وسيغناغي، التي يسمونها مدينة الحب، فيها سور قديم وإطلالة واسعة على وادي ألازاني وجبال القوقاز. وفي تيلافي قصر الملك إريكلي الثاني."},{"kind":"WHERE","heading":"الجبال","body":"كازبيغي من أكثر الأماكن زيارة في جورجيا بعد تبليسي وباتومي. من قرية ستيبانتسميندا تصعد مشيًا أو بالسيارة إلى كنيسة الثالوث في غيرغيتي من القرن الرابع عشر، تحت جبل كازبيك بارتفاع 5054 مترًا. وفي الطريق غوداوري، أشهر منتجع تزلج في البلاد. وإلى الغرب تقع سفانيتي، أرض الجبال العالية، ومركزها ميستيا بأبراجها الحجرية الشهيرة التي يبلغ ارتفاعها بين 20 و25 مترًا، والطريق المعتاد إليها يمر عبر زوغديدي."},{"kind":"WHERE","heading":"الغرب والبحر","body":"كانت كوتايسي العاصمة حتى العصور الوسطى. زُر كاتدرائية باغراتي التي بُنيت عام 1003، ودير غيلاتي المدرج في قائمة اليونسكو، ثم كهف بروميثيوس وساتابليا القريبين. وللبحر هناك باتومي بكورنيشها الطويل على الماء، وأوائل الخريف وقت جميل لزيارتها."},{"kind":"WHERE","heading":"بورجومي وفاردزيا","body":"بورجومي بلدة جبلية صغيرة مشهورة بمياهها المعدنية، ويمكنك الشرب من نبع في الحديقة المركزية. وحولها حديقة بورجومي خاراغاولي الوطنية بمسارات مشي من يوم إلى ثلاثة أيام. وإلى الجنوب فاردزيا، مدينة ودير من العصور الوسطى منحوتان في الصخر."},{"kind":"PRACTICAL","heading":"قبل أن تذهب","body":"طرق الجبال وطقسها يتغيران مع الفصول، فتحقق من النشرة الجوية وحالة الطريق قبل أي رحلة شتوية إلى الشمال أو إلى سفانيتي. خذ جوازك في القطار. وفي القرى احمل بعض النقود، وفي الجبال تكون تغطية Magti عادة هي الأفضل."}]},"he":{"title":"מקומות לבקר בהם","summary":"גאורגיה קטנה, וזו בדיוק החדשה הטובה: הרים גבוהים, כנסיות עתיקות, ארץ היין והים נמצאים כולם במרחק יום מטביליסי.","sections":[{"kind":"SHORT_ANSWER","heading":"בקצרה","body":"התחילו קרוב, במצחטה, ואז סוף שבוע בקאחתי בשביל היין וסיגנאגי. צפונה לקזבגי בשביל ההרים, מערבה לקוטאיסי בשביל מנזרים ומערות, ושמרו כמה ימים לסוואנטי. בקיץ, בטומי והים. באתר התיירות הלאומי georgia.travel יש עוד על כל אחד מהמקומות."},{"kind":"WHERE","heading":"טיולים קלים מטביליסי","body":"מצחטה, הבירה העתיקה, נמצאת בערך 20 דקות נסיעה. שם קתדרלת סווטיצחובלי וכנסיית ג׳ווארי, ושלוש מהכנסיות שלה ברשימת המורשת העולמית של אונסק״ו. קאחתי במזרח היא אזור היין המרכזי של גאורגיה, ועדיין מכינים בה יין בכדי חרס שנקראים קווברי. בסיגנאגי, שקוראים לה עיר האהבה, יש חומה עתיקה ונוף רחב לעמק אלאזאני ולקווקז. בתלאווי נמצא הארמון של המלך ארקלה השני."},{"kind":"WHERE","heading":"ההרים","body":"קזבגי הוא אחד המקומות המתוירים ביותר בגאורגיה אחרי טביליסי ובטומי. מהכפר סטפנצמינדה עולים ברגל או ברכב לכנסיית השילוש של גרגטי מהמאה ה־14, מתחת להר קזבק בגובה 5054 מטר. בדרך נמצא גודאורי, אתר הסקי המוכר ביותר במדינה. מערבה משם סוואנטי, ארץ הרים גבוהים שמרכזה מסטיה, עם מגדלי האבן המפורסמים בגובה 20 עד 25 מטר. בדרך כלל מגיעים לשם דרך זוגדידי."},{"kind":"WHERE","heading":"המערב והים","body":"קוטאיסי הייתה הבירה עד ימי הביניים. בקרו בקתדרלת בגרטי שנבנתה ב־1003 ובמנזר גלאטי שברשימת אונסק״ו, ואחר כך במערת פרומתאוס ובסטאפליה הסמוכות. בשביל הים יש את בטומי, עם טיילת ארוכה לאורך המים, ותחילת הסתיו היא זמן נהדר להגיע."},{"kind":"WHERE","heading":"בורג׳ומי וורדזיה","body":"בורג׳ומי היא עיירת הרים קטנה שמפורסמת במים המינרליים שלה, ואפשר לשתות אותם ממעיין בפארק המרכזי. סביבה פארק בורג׳ומי חרגאולי הלאומי, עם מסלולי הליכה של יום עד שלושה ימים. דרומה משם ורדזיה, עיר ומנזר מימי הביניים שחצובים בצוק."},{"kind":"PRACTICAL","heading":"לפני שיוצאים","body":"כבישי ההרים ומזג האוויר משתנים לפי העונה, אז לפני טיול חורף צפונה או לסוואנטי בדקו תחזית ומצב כבישים. ברכבת צריך דרכון. בכפרים כדאי להחזיק קצת מזומן, ובהרים הקליטה הכי טובה היא בדרך כלל של Magti."}]}}'::jsonb,
        'GENERAL', 'PRACTICAL_CONTEXT', 110,
        true, false, null,
        now(), now() + interval '90 days')
on conflict (slug) do update set
  domain = excluded.domain,
  pathway = excluded.pathway,
  content = excluded.content,
  fact_class = excluded.fact_class,
  register = excluded.register,
  sort_order = excluded.sort_order,
  published = excluded.published,
  needs_review = excluded.needs_review,
  review_reason = excluded.review_reason,
  last_verified_at = excluded.last_verified_at,
  review_due_at = excluded.review_due_at,
  updated_at = now();
insert into public.expat_topic_facts
  (topic_id, fact_key, fact_class, register, availability, statement, value,
   applies_to_nationalities, needs_review)
select id, 'mtskheta-unesco', 'GENERAL', 'PRACTICAL_CONTEXT', 'ESTABLISHED',
       '{"en":"Three of Mtskheta''s churches, Jvari, Svetitskhoveli and Samtavro, are on the UNESCO World Heritage List, and Mtskheta is about 20 minutes by road from Tbilisi. Gelati Monastery near Kutaisi is also a UNESCO World Heritage monument.","ka":"მცხეთის სამი ეკლესია, ჯვარი, სვეტიცხოველი და სამთავრო, იუნესკოს მსოფლიო მემკვიდრეობის სიაშია, მცხეთა კი თბილისიდან მანქანით დაახლოებით 20 წუთშია. ქუთაისთან ახლოს მდებარე გელათის მონასტერიც იუნესკოს მსოფლიო მემკვიდრეობის ძეგლია.","ru":"Три храма Мцхеты, Джвари, Светицховели и Самтавро, входят в список Всемирного наследия ЮНЕСКО, а сама Мцхета примерно в 20 минутах езды от Тбилиси. Монастырь Гелати под Кутаиси также памятник Всемирного наследия ЮНЕСКО.","tr":"Mtsheta''nın üç kilisesi, Cvari, Svetitskhoveli ve Samtavro, UNESCO Dünya Mirası Listesi''ndedir ve Mtsheta Tiflis''e arabayla yaklaşık 20 dakikadır. Kutaisi yakınındaki Gelati Manastırı da UNESCO Dünya Mirası anıtıdır.","ar":"ثلاث من كنائس متسخيتا، جفاري وسفيتيتسخوفيلي وسامتافرو، مدرجة في قائمة اليونسكو للتراث العالمي، وتبعد متسخيتا نحو 20 دقيقة بالسيارة عن تبليسي. ودير غيلاتي قرب كوتايسي معلم من معالم التراث العالمي لليونسكو أيضًا.","he":"שלוש כנסיות במצחטה, ג׳ווארי, סווטיצחובלי וסמטברו, נמצאות ברשימת המורשת העולמית של אונסק״ו, ומצחטה נמצאת בערך 20 דקות נסיעה מטביליסי. גם מנזר גלאטי ליד קוטאיסי הוא אתר מורשת עולמית של אונסק״ו."}'::jsonb, null, null,
       false
from public.expat_topics where slug = 'places-to-visit'
on conflict (topic_id, fact_key) do update set
  fact_class = excluded.fact_class,
  register = excluded.register,
  availability = excluded.availability,
  statement = excluded.statement,
  value = excluded.value,
  applies_to_nationalities = excluded.applies_to_nationalities,
  needs_review = excluded.needs_review,
  updated_at = now();
insert into public.expat_fact_citations (fact_id, citation_id)
select f.id, c.id
from public.expat_topic_facts f
join public.expat_topics t on t.id = f.topic_id and t.slug = 'places-to-visit'
cross join lateral (
  select id from public.expat_citations
  where publisher = 'Georgian National Tourism Administration (georgia.travel)' and url is not distinct from 'https://georgia.travel/cities-towns/mtskheta'
  order by created_at limit 1) c
where f.fact_key = 'mtskheta-unesco'
on conflict do nothing;
