insert into public.expat_topic_facts
  (topic_id, fact_key, fact_class, register, availability, statement, value,
   applies_to_nationalities, needs_review)
select id, 'kazbegi-popular', 'GENERAL', 'PRACTICAL_CONTEXT', 'ESTABLISHED',
       '{"en":"After Tbilisi and Batumi, Kazbegi is one of Georgia''s most popular destinations, with the 14th century Gergeti Trinity Church below Mount Kazbek (5054 m). Kakheti is Georgia''s main wine region, Mestia is the centre of Zemo Svaneti, and Borjomi is known for its mineral water.","ka":"თბილისისა და ბათუმის შემდეგ ყაზბეგი საქართველოს ერთ-ერთი ყველაზე პოპულარული მიმართულებაა, XIV საუკუნის გერგეტის სამებით მყინვარწვერის (5054 მ) ძირას. კახეთი საქართველოს მთავარი ღვინის მხარეა, მესტია ზემო სვანეთის ცენტრია, ბორჯომი კი მინერალური წყლით არის ცნობილი.","ru":"После Тбилиси и Батуми Казбеги одно из самых популярных направлений Грузии, с церковью Гергети Самеба XIV века у подножия Казбека (5054 м). Кахетия главный винный регион Грузии, Местиа центр Верхней Сванетии, а Боржоми известен минеральной водой.","tr":"Tiflis ve Batum''dan sonra Kazbegi, Kazbek Dağı''nın (5054 m) eteğindeki 14. yüzyıl Gergeti Sameba Kilisesi ile Gürcistan''ın en popüler yerlerinden biridir. Kaheti Gürcistan''ın ana şarap bölgesi, Mestia Yukarı Svaneti''nin merkezidir, Borjomi ise maden suyuyla bilinir.","ar":"بعد تبليسي وباتومي تُعد كازبيغي من أشهر الوجهات في جورجيا، وفيها كنيسة الثالوث في غيرغيتي من القرن الرابع عشر تحت جبل كازبيك (5054 م). وكاخيتي منطقة النبيذ الرئيسية في جورجيا، وميستيا مركز سفانيتي العليا، وبورجومي معروفة بمياهها المعدنية.","he":"אחרי טביליסי ובטומי, קזבגי הוא אחד היעדים הפופולריים ביותר בגאורגיה, עם כנסיית השילוש של גרגטי מהמאה ה־14 מתחת להר קזבק (5054 מ׳). קאחתי הוא אזור היין המרכזי של גאורגיה, מסטיה היא מרכז סוואנטי העליונה, ובורג׳ומי ידועה במים המינרליים שלה."}'::jsonb, null, null,
       false
