-- everyday-tips
insert into public.expat_topics
  (slug, country, domain, pathway, content, fact_class, register, sort_order,
   published, needs_review, review_reason, last_verified_at, review_due_at)
values ('everyday-tips', 'GE', 'DAILY_LIFE', 'LIVE', '{"en":{"title":"Everyday tips","summary":"The small things that make the first weeks easier: money, tipping, water, finding your way and a few words of Georgian.","sections":[{"kind":"SHORT_ANSWER","heading":"The short answer","body":"The money is the Georgian lari (GEL), and smaller coins are tetri. Cards work in most shops and cafes in the cities, but keep some cash for markets, minibuses and villages. Tipping is welcome but not required. Learn to say hello and thank you in Georgian, and people will smile."},{"kind":"PRACTICAL","heading":"Money","body":"Prices are in lari. Paying by card, including tapping your phone, is normal in city shops, supermarkets and most cafes. Small shops, markets, minibuses and village guesthouses often want cash. Cash machines and exchange offices are easy to find in cities."},{"kind":"PRACTICAL","heading":"Tipping","body":"Tipping is a custom, not a rule. For good service in a restaurant, 10% to 15% is a common guide, but it is up to you. Look at the bill first, because some places already add a service charge. With some bank cards you can add the tip on the card machine."},{"kind":"PRACTICAL","heading":"Tap water","body":"In Tbilisi and Batumi the water companies say tap water meets drinking standards. Old buildings can have old pipes, so a filter or bottled water is the safer choice there. In villages and the mountains spring water is not always tested, so boil it first. If you have a sensitive stomach or small children, start with bottled water."},{"kind":"PRACTICAL","heading":"Finding your way","body":"Street names are written in Georgian script and spelled in many ways in Latin letters, so a map pin is easier than an address. Share your location when you order a taxi or a delivery. Ask a neighbour or your landlord which apps people use locally."},{"kind":"NOTES","heading":"A few words of Georgian","body":"Georgian has its own alphabet, and a few words go a long way. Gamarjoba is hello. Madloba is thank you. Ki is yes, ara is no. Nakhvamdis is goodbye. In the cities many younger people speak English, and many older people speak Russian."}]},"ka":{"title":"ყოველდღიური რჩევები","summary":"წვრილმანები, რომლებიც პირველ კვირებს ამარტივებს: ფული, გასამრჯელო, წყალი, გზის პოვნა და რამდენიმე ქართული სიტყვა.","sections":[{"kind":"SHORT_ANSWER","heading":"მოკლე პასუხი","body":"ფული ქართული ლარია (GEL), წვრილი მონეტები კი თეთრია. ქალაქებში მაღაზიებისა და კაფეების უმეტესობაში ბარათი მუშაობს, მაგრამ ბაზრისთვის, მარშრუტკისა და სოფლებისთვის ცოტა ნაღდი ფული იქონიეთ. გასამრჯელოს დატოვება მისასალმებელია, მაგრამ სავალდებულო არ არის. ისწავლეთ ქართულად გამარჯობა და მადლობა, და ხალხი გაგიღიმებთ."},{"kind":"PRACTICAL","heading":"ფული","body":"ფასები ლარშია. ბარათით გადახდა, ტელეფონის მიდებითაც, ჩვეულებრივია ქალაქის მაღაზიებში, სუპერმარკეტებში და კაფეების უმეტესობაში. პატარა მაღაზიები, ბაზრები, მარშრუტკები და სოფლის საოჯახო სასტუმროები ხშირად ნაღდს ითხოვენ. ქალაქებში ბანკომატი და ვალუტის გადამცვლელი ადვილად მოიძებნება."},{"kind":"PRACTICAL","heading":"გასამრჯელო","body":"გასამრჯელო ჩვეულებაა და არა წესი. რესტორანში კარგი მომსახურებისთვის 10%-დან 15%-მდე ჩვეულებრივი ორიენტირია, მაგრამ ეს თქვენი გადასაწყვეტია. ჯერ ანგარიში ნახეთ, რადგან ზოგან მომსახურების საფასური უკვე დამატებულია. ზოგი საბანკო ბარათით გასამრჯელოს დამატება ტერმინალზეც შეიძლება."},{"kind":"PRACTICAL","heading":"ონკანის წყალი","body":"თბილისსა და ბათუმში წყალმომარაგების კომპანიები ამბობენ, რომ ონკანის წყალი სასმელი წყლის სტანდარტებს აკმაყოფილებს. ძველ შენობებში მილები შეიძლება ძველი იყოს, ამიტომ იქ ფილტრი ან ბოთლის წყალი უფრო უსაფრთხოა. სოფლებსა და მთაში წყაროს წყალი ყოველთვის არ მოწმდება, ამიტომ ჯერ აადუღეთ. თუ მგრძნობიარე კუჭი გაქვთ ან პატარა ბავშვები გყავთ, ბოთლის წყლით დაიწყეთ."},{"kind":"PRACTICAL","heading":"როგორ იპოვოთ გზა","body":"ქუჩების სახელები ქართული ასოებითაა დაწერილი და ლათინურად ბევრნაირად იწერება, ამიტომ რუკაზე წერტილი მისამართზე მარტივია. ტაქსის ან მიტანის შეკვეთისას გაუზიარეთ თქვენი ადგილმდებარეობა. ჰკითხეთ მეზობელს ან მესაკუთრეს, რომელ აპლიკაციებს იყენებენ აქ."},{"kind":"NOTES","heading":"რამდენიმე ქართული სიტყვა","body":"ქართულს თავისი ანბანი აქვს და უცხოელისთვის რამდენიმე სიტყვაც ბევრს ნიშნავს: გამარჯობა, მადლობა, კი, არა, ნახვამდის. ქალაქებში ბევრი ახალგაზრდა ინგლისურად ლაპარაკობს, უფროსი თაობიდან კი ბევრი რუსულად."}]},"ru":{"title":"Полезные мелочи на каждый день","summary":"Мелочи, которые облегчают первые недели: деньги, чаевые, вода, как ориентироваться и несколько грузинских слов.","sections":[{"kind":"SHORT_ANSWER","heading":"Коротко","body":"Валюта это грузинский лари (GEL), мелкие монеты называются тетри. В городах карта работает в большинстве магазинов и кафе, но держите немного наличных для рынков, маршруток и сёл. Чаевые приветствуются, но не обязательны. Выучите, как по-грузински сказать «здравствуйте» и «спасибо», и люди будут улыбаться."},{"kind":"PRACTICAL","heading":"Деньги","body":"Цены указаны в лари. Платить картой, в том числе телефоном, обычное дело в городских магазинах, супермаркетах и большинстве кафе. Маленькие магазины, рынки, маршрутки и гостевые дома в сёлах часто хотят наличные. Банкоматы и обменники в городах легко найти."},{"kind":"PRACTICAL","heading":"Чаевые","body":"Чаевые это обычай, а не правило. За хорошее обслуживание в ресторане обычно ориентируются на 10% до 15%, но решать вам. Сначала посмотрите счёт: в некоторых местах плата за обслуживание уже добавлена. С некоторыми банковскими картами чаевые можно добавить прямо на терминале."},{"kind":"PRACTICAL","heading":"Вода из крана","body":"В Тбилиси и Батуми водоканалы говорят, что вода из крана соответствует стандартам питьевой воды. В старых домах трубы могут быть старыми, поэтому там надёжнее фильтр или бутилированная вода. В сёлах и горах родниковую воду не всегда проверяют, так что сначала прокипятите. Если у вас чувствительный желудок или маленькие дети, начните с бутилированной воды."},{"kind":"PRACTICAL","heading":"Как ориентироваться","body":"Названия улиц написаны грузинскими буквами и по-разному передаются латиницей, поэтому точка на карте проще адреса. Когда заказываете такси или доставку, делитесь геолокацией. Спросите соседа или хозяина квартиры, какими приложениями здесь пользуются."},{"kind":"NOTES","heading":"Несколько грузинских слов","body":"У грузинского свой алфавит, и даже пара слов очень помогает. Гамарджоба значит здравствуйте. Мадлоба значит спасибо. Ки это да, ара это нет. Нахвамдис значит до свидания. В городах многие молодые говорят по-английски, а многие люди постарше по-русски."}]},"tr":{"title":"Günlük ipuçları","summary":"İlk haftaları kolaylaştıran küçük şeyler: para, bahşiş, su, yol bulmak ve birkaç Gürcüce kelime.","sections":[{"kind":"SHORT_ANSWER","heading":"Kısaca","body":"Para birimi Gürcü larisi (GEL), küçük bozukluklar tetri. Şehirlerde çoğu mağaza ve kafede kart geçer, ama pazarlar, minibüsler ve köyler için biraz nakit bulundurun. Bahşiş hoş karşılanır ama zorunlu değildir. Gürcüce merhaba ve teşekkür ederim demeyi öğrenin, insanlar gülümser."},{"kind":"PRACTICAL","heading":"Para","body":"Fiyatlar lari cinsindendir. Kartla ödemek, telefonla temassız ödeme dahil, şehirdeki mağazalarda, süpermarketlerde ve çoğu kafede olağandır. Küçük dükkânlar, pazarlar, minibüsler ve köy pansiyonları çoğu zaman nakit ister. Şehirlerde ATM ve döviz bürosu bulmak kolaydır."},{"kind":"PRACTICAL","heading":"Bahşiş","body":"Bahşiş bir gelenektir, kural değildir. Restoranda iyi hizmet için %10 ila %15 yaygın bir ölçüdür, ama karar sizin. Önce hesaba bakın, bazı yerler servis ücretini zaten ekler. Bazı banka kartlarıyla bahşişi kart makinesinde ekleyebilirsiniz."},{"kind":"PRACTICAL","heading":"Musluk suyu","body":"Tiflis ve Batum''da su şirketleri musluk suyunun içme suyu standartlarını karşıladığını söylüyor. Eski binalarda borular eski olabilir, oralarda filtre ya da şişe suyu daha güvenlidir. Köylerde ve dağlarda kaynak suyu her zaman test edilmez, önce kaynatın. Hassas bir mideniz ya da küçük çocuklarınız varsa şişe suyuyla başlayın."},{"kind":"PRACTICAL","heading":"Yol bulmak","body":"Sokak adları Gürcü alfabesiyle yazılır ve Latin harfleriyle pek çok şekilde yazılır, bu yüzden haritada bir konum işareti adresten kolaydır. Taksi ya da sipariş verirken konumunuzu paylaşın. Komşunuza ya da ev sahibinize burada hangi uygulamaların kullanıldığını sorun."},{"kind":"NOTES","heading":"Birkaç Gürcüce kelime","body":"Gürcücenin kendi alfabesi var ve birkaç kelime bile çok işe yarar. Gamarjoba merhaba demek. Madloba teşekkürler. Ki evet, ara hayır. Nakhvamdis hoşça kal. Şehirlerde birçok genç İngilizce, birçok yaşlı ise Rusça konuşur."}]},"ar":{"title":"نصائح للحياة اليومية","summary":"أشياء صغيرة تسهّل الأسابيع الأولى: المال والبقشيش والماء ومعرفة الطريق وبضع كلمات جورجية.","sections":[{"kind":"SHORT_ANSWER","heading":"باختصار","body":"العملة هي اللاري الجورجي (GEL)، والقطع النقدية الصغيرة اسمها تيتري. البطاقة تعمل في معظم المحلات والمقاهي في المدن، لكن احتفظ ببعض النقود للأسواق والميني باص والقرى. البقشيش مُرحَّب به لكنه غير واجب. وتعلّم أن تقول مرحبًا وشكرًا بالجورجية، وسترى الابتسامات."},{"kind":"PRACTICAL","heading":"المال","body":"الأسعار باللاري. الدفع بالبطاقة، ومنه الدفع بالهاتف، أمر عادي في محلات المدن والسوبرماركت ومعظم المقاهي. أما المحلات الصغيرة والأسواق والميني باص وبيوت الضيافة في القرى فكثيرًا ما تطلب النقد. وأجهزة الصراف ومكاتب الصرافة سهلة الإيجاد في المدن."},{"kind":"PRACTICAL","heading":"البقشيش","body":"البقشيش عادة وليس قاعدة. للخدمة الجيدة في المطعم يُعد 10% إلى 15% دليلًا شائعًا، لكن القرار لك. انظر إلى الفاتورة أولًا، فبعض الأماكن تضيف رسم الخدمة مسبقًا. ومع بعض البطاقات البنكية يمكنك إضافة البقشيش على جهاز الدفع."},{"kind":"PRACTICAL","heading":"ماء الحنفية","body":"في تبليسي وباتومي تقول شركات المياه إن ماء الحنفية مطابق لمعايير مياه الشرب. لكن المباني القديمة قد تكون أنابيبها قديمة، فالفلتر أو الماء المعبأ أكثر أمانًا هناك. وفي القرى والجبال لا تُفحص مياه الينابيع دائمًا، فاغلِها أولًا. وإن كانت معدتك حساسة أو معك أطفال صغار فابدأ بالماء المعبأ."},{"kind":"PRACTICAL","heading":"كيف تجد طريقك","body":"أسماء الشوارع مكتوبة بالحروف الجورجية وتُكتب بالحروف اللاتينية بطرق كثيرة، لذلك تحديد الموقع على الخريطة أسهل من العنوان. شارك موقعك عند طلب سيارة أجرة أو توصيل. واسأل جارك أو المالك عن التطبيقات التي يستخدمها الناس هنا."},{"kind":"NOTES","heading":"بضع كلمات جورجية","body":"للجورجية أبجدية خاصة بها، وبضع كلمات تفتح لك قلوبًا كثيرة. غامارجوبا تعني مرحبًا. مادلوبا تعني شكرًا. كي تعني نعم، وآرا تعني لا. ناخفامديس تعني إلى اللقاء. في المدن يتكلم كثير من الشباب الإنجليزية، وكثير من الأكبر سنًا الروسية."}]},"he":{"title":"טיפים ליומיום","summary":"הדברים הקטנים שמקלים על השבועות הראשונים: כסף, טיפ, מים, איך מתמצאים וכמה מילים בגאורגית.","sections":[{"kind":"SHORT_ANSWER","heading":"בקצרה","body":"המטבע הוא הלארי הגאורגי (GEL), והמטבעות הקטנים נקראים טטרי. בערים כרטיס אשראי עובד ברוב החנויות ובתי הקפה, אבל כדאי להחזיק קצת מזומן לשווקים, למיניבוסים ולכפרים. טיפ מתקבל בברכה אבל הוא לא חובה. למדו להגיד שלום ותודה בגאורגית, ואנשים יחייכו."},{"kind":"PRACTICAL","heading":"כסף","body":"המחירים בלארי. תשלום בכרטיס, כולל בהצמדת הטלפון, הוא דבר רגיל בחנויות בעיר, בסופרמרקטים וברוב בתי הקפה. חנויות קטנות, שווקים, מיניבוסים ובתי הארחה בכפרים רוצים הרבה פעמים מזומן. כספומטים ומשרדי המרה קל למצוא בערים."},{"kind":"PRACTICAL","heading":"טיפ","body":"טיפ הוא מנהג, לא חוק. על שירות טוב במסעדה, 10% עד 15% זו הנחיה מקובלת, אבל ההחלטה שלכם. הסתכלו קודם על החשבון, כי יש מקומות שכבר מוסיפים דמי שירות. עם חלק מכרטיסי הבנק אפשר להוסיף את הטיפ במסוף התשלום."},{"kind":"PRACTICAL","heading":"מי ברז","body":"בטביליסי ובבטומי חברות המים אומרות שמי הברז עומדים בתקני מי שתייה. בבניינים ישנים הצנרת יכולה להיות ישנה, אז שם עדיף פילטר או מים בבקבוק. בכפרים ובהרים מי המעיינות לא תמיד נבדקים, אז הרתיחו קודם. אם יש לכם קיבה רגישה או ילדים קטנים, התחילו עם מים בבקבוק."},{"kind":"PRACTICAL","heading":"איך מתמצאים","body":"שמות הרחובות כתובים באותיות גאורגיות ונכתבים באותיות לטיניות בהרבה צורות, אז נעץ במפה פשוט יותר מכתובת. כשמזמינים מונית או משלוח, שתפו מיקום. שאלו שכן או את בעל הדירה באילו אפליקציות משתמשים כאן."},{"kind":"NOTES","heading":"כמה מילים בגאורגית","body":"לגאורגית יש אלפבית משלה, וכמה מילים עושות הרבה. גמרג׳ובה זה שלום. מדלובה זה תודה. קי זה כן, ארה זה לא. נחוומדיס זה להתראות. בערים הרבה צעירים מדברים אנגלית, והרבה מבוגרים מדברים רוסית."}]}}'::jsonb,
        'GENERAL', 'PRACTICAL_CONTEXT', 120,
        true, false, null,
        now(), now() + interval '90 days')
