  last_verified_at = excluded.last_verified_at,
  review_due_at = excluded.review_due_at,
  updated_at = now();
insert into public.expat_topic_facts
  (topic_id, fact_key, fact_class, register, availability, statement, value,
   applies_to_nationalities, needs_review)
select id, 'currency-lari', 'GENERAL', 'OFFICIAL_REQUIREMENT', 'ESTABLISHED',
       '{"en":"The lari (GEL) is the basic monetary unit of Georgia''s national currency, issued by the National Bank of Georgia. Smaller coins are in tetri.","ka":"ლარი (GEL) საქართველოს ეროვნული ვალუტის ძირითადი ერთეულია, რომელსაც საქართველოს ეროვნული ბანკი უშვებს. წვრილი მონეტები თეთრშია.","ru":"Лари (GEL) это основная денежная единица национальной валюты Грузии, её выпускает Национальный банк Грузии. Мелкие монеты в тетри.","tr":"Lari (GEL), Gürcistan Ulusal Bankası''nın çıkardığı Gürcistan ulusal para biriminin temel birimidir. Küçük madeni paralar tetri cinsindendir.","ar":"اللاري (GEL) هو الوحدة النقدية الأساسية للعملة الوطنية في جورجيا، ويصدرها البنك الوطني الجورجي. والقطع الصغيرة بالتيتري.","he":"הלארי (GEL) הוא יחידת המטבע הבסיסית של המטבע הלאומי של גאורגיה, ומנפיק אותו הבנק הלאומי של גאורגיה. המטבעות הקטנים הם בטטרי."}'::jsonb, '{"currency":"GEL"}'::jsonb, null,
       false
from public.expat_topics where slug = 'everyday-tips'
on conflict (topic_id, fact_key) do update set
