  updated_at = now();
insert into public.expat_fact_citations (fact_id, citation_id)
select f.id, c.id
from public.expat_topic_facts f
join public.expat_topics t on t.id = f.topic_id and t.slug = 'everyday-tips'
cross join lateral (
  select id from public.expat_citations
  where publisher = 'National Bank of Georgia' and url is not distinct from 'https://nbg.gov.ge/en/georgian-money/georgian-lari'
  order by created_at limit 1) c
where f.fact_key = 'currency-lari'
on conflict do nothing;
insert into public.expat_topic_facts
  (topic_id, fact_key, fact_class, register, availability, statement, value,
   applies_to_nationalities, needs_review)
select id, 'tipping-custom', 'GENERAL', 'COMMUNITY_EXPERIENCE', 'ESTABLISHED',
       '{"en":"Tipping is a custom, not a rule. Georgia''s national tourism site gives 10% to 15% of the bill as a good guide, and says it depends on you.","ka":"გასამრჯელო ჩვეულებაა და არა წესი. საქართველოს ეროვნული ტურისტული საიტი კარგ ორიენტირად ანგარიშის 10%-დან 15%-მდე ასახელებს და ამბობს, რომ ეს თქვენზეა დამოკიდებული.","ru":"Чаевые это обычай, а не правило. Национальный туристический сайт Грузии называет хорошим ориентиром 10% до 15% от счёта и пишет, что решать вам.","tr":"Bahşiş bir gelenektir, kural değildir. Gürcistan''ın ulusal turizm sitesi hesabın %10 ila %15''ini iyi bir ölçü olarak verir ve bunun size bağlı olduğunu söyler.","ar":"البقشيش عادة وليس قاعدة. ويذكر موقع السياحة الوطني في جورجيا أن 10% إلى 15% من الفاتورة دليل جيد، وأن الأمر يعود إليك.","he":"טיפ הוא מנהג, לא חוק. אתר התיירות הלאומי של גאורגיה מציין 10% עד 15% מהחשבון כהנחיה טובה, ואומר שזה תלוי בכם."}'::jsonb, '{"tipPctLow":10,"tipPctHigh":15}'::jsonb, null,
       false
