insert into public.expat_topic_facts
  (topic_id, fact_key, fact_class, register, availability, statement, value,
   applies_to_nationalities, needs_review)
select id, 'tap-water', 'GENERAL', 'PRACTICAL_CONTEXT', 'ESTABLISHED',
       '{"en":"In Tbilisi and Batumi the water utilities say tap water meets drinking standards. In older buildings a filter or bottled water is safer, and spring water in villages and mountains is not always tested.","ka":"თბილისსა და ბათუმში წყალმომარაგების კომპანიები ამბობენ, რომ ონკანის წყალი სასმელი წყლის სტანდარტებს აკმაყოფილებს. ძველ შენობებში ფილტრი ან ბოთლის წყალი უფრო უსაფრთხოა, სოფლებსა და მთაში კი წყაროს წყალი ყოველთვის არ მოწმდება.","ru":"В Тбилиси и Батуми водоканалы говорят, что вода из крана соответствует стандартам питьевой воды. В старых домах надёжнее фильтр или бутилированная вода, а родниковую воду в сёлах и горах проверяют не всегда.","tr":"Tiflis ve Batum''da su şirketleri musluk suyunun içme suyu standartlarını karşıladığını söylüyor. Eski binalarda filtre ya da şişe suyu daha güvenlidir, köylerde ve dağlarda kaynak suyu her zaman test edilmez.","ar":"في تبليسي وباتومي تقول شركات المياه إن ماء الحنفية مطابق لمعايير مياه الشرب. وفي المباني القديمة الفلتر أو الماء المعبأ أكثر أمانًا، ومياه الينابيع في القرى والجبال لا تُفحص دائمًا.","he":"בטביליסי ובבטומי חברות המים אומרות שמי הברז עומדים בתקני מי שתייה. בבניינים ישנים פילטר או מים בבקבוק בטוחים יותר, ומי מעיינות בכפרים ובהרים לא תמיד נבדקים."}'::jsonb, null, null,
       false
